-- FlightDeck catalogue seed (FD-C01). GENERATED FILE: do not edit by hand.
-- Source: content/** + packages/database/seeds/catalogue.config.json
-- Regenerate: pnpm --filter @flightdeck/database seed:generate
-- Counts: tracks=3 courses=2 course_versions=2 missions=4 mission_steps=20 exercises=5 exercise_keys=5 assessments=4 assessment_items=16 assessment_item_keys=16
-- Public tables receive learner-safe data only; answer keys and hidden tests go to app_private only.
-- Requires the seed author and reviewer in auth.users (local/test: seeds/local-users.sql; production: see docs/data/CATALOGUE-SEEDING.md).
-- Idempotent: every insert is "on conflict do nothing". Published rows are never updated: a content change is a new course version.

begin;

do $$
begin
  if (select count(*) from auth.users where email in ('content-author@flightdeck.local', 'content-reviewer@flightdeck.local')) <> 2 then
    raise exception 'catalogue seed: seed author/reviewer missing from auth.users (apply seeds/local-users.sql locally, or create the accounts; see docs/data/CATALOGUE-SEEDING.md)';
  end if;
end;
$$;

-- Tracks
on conflict do nothing;

-- Courses
on conflict do nothing;

-- Course versions (published; a new content round = a new version row)
on conflict do nothing;

-- Review record: the seed reviewer was the assigned reviewer of each seeded version
on conflict do nothing;

-- Exercises (learner-safe definition only)
on conflict do nothing;

-- Exercise keys (SERVER-ONLY: expected values and hidden tests)
on conflict do nothing;

-- Assessments
on conflict do nothing;

-- Assessment items (prompt and options only)
on conflict do nothing;

-- Assessment item keys (SERVER-ONLY)
on conflict do nothing;

-- Missions
on conflict do nothing;

-- Mission steps
on conflict do nothing;

-- Audit trail for the seeded publications (once per version)
select '2026-11-11T00:00:00Z'::timestamptz, (select id from auth.users where email = 'content-reviewer@flightdeck.local'), 'publish', 'course_version', v.id::text,
       jsonb_build_object('course_id', v.course_id, 'version', v.version, 'source', 'catalogue seed')
  from public.course_versions v
 where v.id in ('e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'a49c2a77-9fb5-5aae-aba1-bfb5249ed8f1')
   and not exists (select 1 from app_private.audit_log l
                    where l.entity = 'course_version' and l.entity_id = v.id::text and l.action = 'publish');

commit;
