insert into public.exercises (id, course_version_id, kind, slug, title, definition) values
  ('0660b26f-d024-5d1e-a03e-9e9b10ffebe5', 'a49c2a77-9fb5-5aae-aba1-bfb5249ed8f1', 'math', 'descriptive-stats-101-practice', 'Typical week: mean, median and spread: practice', '{"schemaVersion":1,"missionSlug":"descriptive-stats-101","datasets":[{"id":"store-a-weekly-pairs","title":"Store A: pairs sold per week, weeks 1 to 10","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9","Wk 10"],"values":[132,148,141,155,139,150,146,158,144,312],"adjustable":{"index":9,"min":100,"max":400,"step":1,"label":"Week 10 (school reopening)"},"spread":"sample","decimals":1},{"id":"store-b-weekly-pairs","title":"Store B: pairs sold per week, weeks 1 to 9","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9"],"values":[86,94,78,91,240,88,83,97,90],"adjustable":{"index":4,"min":50,"max":300,"step":1,"label":"Week 5 (bulk school order)"},"spread":"sample","decimals":1}],"practice":[{"id":"practice-mean-store-a","prompt":"Calculate the mean number of pairs Store A sold per week. Round to 1 decimal place.","datasetId":"store-a-weekly-pairs","statistic":"mean","decimals":1,"tolerance":{"kind":"absolute","value":0.05}},{"id":"practice-median-store-a","prompt":"Now find the median pairs sold per week for Store A.","datasetId":"store-a-weekly-pairs","statistic":"median","decimals":1,"tolerance":{"kind":"absolute","value":0.05}}]}'::jsonb),
  ('59f167a1-9ecd-5248-82dd-64d562b86a7f', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'commission-tier-if-chain', 'Commission tiers: a lookup with nested IF', '{"schemaVersion":1,"id":"commission-tier-if-chain","version":1,"title":"Commission tiers: a lookup with nested IF","objective":"Look up a value from a tier table with nested IF and absolute references (the v0 substitute for an approximate-match lookup).","instructions":"In C2:C5, return each rep''s commission rate from the tier table in F1:G4. Use the highest tier whose \"Sales from\" amount the rep has reached. Refer to the table cells (for example $G$3) instead of typing the rates.","grid":{"rows":5,"cols":7},"starter":{"A1":"Rep","B1":"Sales","C1":"Rate","A2":"Amina","B2":"42000","A3":"Brian","B3":"50000","A4":"Chao","B4":"87500","A5":"Dalia","B5":"125000","F1":"Sales from","G1":"Rate","F2":"0","G2":"2%","F3":"50000","G3":"4%","F4":"100000","G4":"6%"},"editableCells":["C2","C3","C4","C5"],"allowedFunctions":["IF"],"hints":["Check the highest tier first: =IF(B2>=$F$4, $G$4, ...).","Put a second IF in the value_if_false part for the middle tier, and use $G$2 as the last fallback.","The $ signs keep the table references fixed when you reuse the formula on the next row; B2 changes to B3."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('d3e774f4-b56e-559d-ba30-326b7470fc0e', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'if-business-thresholds', 'Stock reorder flags with IF', '{"schemaVersion":1,"id":"if-business-thresholds","version":1,"title":"Stock reorder flags with IF","objective":"Use IF with a comparison to flag a business threshold.","instructions":"In D2:D5, show \"Reorder\" when the stock on hand is at or below the reorder point, otherwise show \"OK\".","grid":{"rows":5,"cols":4},"starter":{"A1":"Item","B1":"On hand","C1":"Reorder point","D1":"Action","A2":"Sneakers","B2":"40","C2":"25","A3":"Sandals","B3":"12","C3":"20","A4":"Boots","B4":"30","C4":"30","A5":"School shoes","B5":"8","C5":"15"},"editableCells":["D2","D3","D4","D5"],"allowedFunctions":["IF"],"hints":["IF has three parts: =IF(condition, value_if_true, value_if_false).","\"At or below\" is the comparison <=.","Text results need double quotes, for example \"Reorder\"."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('4e2cde94-010e-5dec-a2c2-da00e668b7cb', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sum-relative-refs', 'Quarter totals with SUM', '{"schemaVersion":1,"id":"sum-relative-refs","version":1,"title":"Quarter totals with SUM","objective":"Total a column with SUM and reuse the same formula pattern for the next column (relative references).","instructions":"In B5, total North''s sales for January to March. Then total South''s sales in C5 with the same pattern, shifted one column.","grid":{"rows":5,"cols":3},"starter":{"A1":"Month","B1":"North (K)","C1":"South (K)","A2":"Jan","B2":"120","C2":"80","A3":"Feb","B3":"95","C3":"110","A4":"Mar","B4":"143","C4":"97","A5":"Total"},"editableCells":["B5","C5"],"allowedFunctions":["SUM"],"hints":["A formula starts with =. SUM adds every number in a range.","A range uses a colon: B2:B4 means B2 through B4.","Relative references shift with the formula: if B5 refers to B2, the same pattern in C5 refers to C2."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('79f8240c-dcab-5f51-8130-94b498e8a4de', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'xlookup-price-list', 'Unit prices with XLOOKUP', '{"schemaVersion":1,"id":"xlookup-price-list","version":1,"title":"Unit prices with XLOOKUP","objective":"Look up a value from a product table with an exact-match XLOOKUP, fixed table references and a not-found fallback.","instructions":"In C2:C5, look up each order line''s unit price (KES) from the price list in E1:G6 with XLOOKUP. Fix the price list with $ signs so the formula can be reused on every row. If a code is not on the price list, show the text \"Not listed\" instead of #N/A.","grid":{"rows":6,"cols":7},"starter":{"A1":"Line","B1":"Product code","C1":"Unit price","A2":"1","B2":"SS-210","A3":"2","B3":"SN-450","A4":"3","B4":"sd-120","A5":"4","B5":"GB-610","E1":"Code","F1":"Product","G1":"Price (KES)","E2":"SS-210","F2":"School shoe","G2":"2499","E3":"SN-450","F3":"Canvas sneaker","G3":"1999","E4":"SD-120","F4":"Ladies sandal","G4":"899","E5":"BT-330","F5":"Ankle boot","G5":"4599","E6":"SL-075","F6":"Slipper","G6":"499"},"editableCells":["C2","C3","C4","C5"],"allowedFunctions":["XLOOKUP"],"hints":["XLOOKUP has three parts plus an optional fourth: =XLOOKUP(what to find, where to look, what to return, [if not found]).","Look for the code in B2 inside the Code column of the price list, and return the matching cell from the Price column.","Add $ signs to the price list ranges (for example $E$2:$E$6) so they stay fixed on every row, while B2 becomes B3, B4 and B5.","Text matching ignores upper and lower case, so \"sd-120\" finds \"SD-120\". The fourth argument, in double quotes, replaces #N/A."],"namedRanges":{},"timeoutMs":500}'::jsonb)
insert into app_private.exercise_keys (exercise_id, expected, hidden_tests, updated_at) values
  ('0660b26f-d024-5d1e-a03e-9e9b10ffebe5', '{"schemaVersion":1,"derivedFrom":"public datasets","items":[{"id":"practice-mean-store-a","type":"numeric","expected":162.5,"tolerance":{"kind":"absolute","value":0.05}},{"id":"practice-median-store-a","type":"numeric","expected":147,"tolerance":{"kind":"absolute","value":0.05}}]}'::jsonb, '[]'::jsonb, '2026-11-11T00:00:00Z'::timestamptz),
  ('59f167a1-9ecd-5248-82dd-64d562b86a7f', '{"schemaVersion":1,"exerciseId":"commission-tier-if-chain","exerciseVersion":1,"expected":[{"id":"amina","cell":"C2","value":0.02,"label":"Amina''s rate"},{"id":"brian","cell":"C3","value":0.04,"label":"Brian''s rate (exactly at a tier boundary)"},{"id":"chao","cell":"C4","value":0.04,"label":"Chao''s rate"},{"id":"dalia","cell":"C5","value":0.06,"label":"Dalia''s rate"}],"requireFormula":["C2","C3","C4","C5"],"requireFunctions":{"C2":["IF"],"C3":["IF"],"C4":["IF"],"C5":["IF"]},"passThreshold":100}'::jsonb, '[{"id":"new-rates","label":"rates come from the tier table","overrides":{"G2":"1%","G3":"3%","G4":"5%"},"expect":{"C2":0.01,"C3":0.03,"C4":0.03,"C5":0.05}},{"id":"new-thresholds","label":"tiers follow the table thresholds","overrides":{"F3":"40000","F4":"80000"},"expect":{"C2":0.04,"C3":0.04,"C4":0.06,"C5":0.06}},{"id":"new-sales","label":"rates update when sales change","overrides":{"B2":"100000","B3":"49999.99","B4":"0","B5":"50000"},"expect":{"C2":0.06,"C3":0.02,"C4":0.02,"C5":0.04}}]'::jsonb, '2026-11-11T00:00:00Z'::timestamptz),
  ('d3e774f4-b56e-559d-ba30-326b7470fc0e', '{"schemaVersion":1,"exerciseId":"if-business-thresholds","exerciseVersion":1,"expected":[{"id":"sneakers","cell":"D2","value":"OK","label":"Sneakers flag"},{"id":"sandals","cell":"D3","value":"Reorder","label":"Sandals flag"},{"id":"boots","cell":"D4","value":"Reorder","label":"Boots flag (exactly at the reorder point)"},{"id":"school-shoes","cell":"D5","value":"Reorder","label":"School shoes flag"}],"requireFormula":["D2","D3","D4","D5"],"requireFunctions":{"D2":["IF"],"D3":["IF"],"D4":["IF"],"D5":["IF"]},"passThreshold":100}'::jsonb, '[{"id":"stock-changes","label":"flags update when stock on hand changes","overrides":{"B2":"10","B3":"50","B4":"31","B5":"15"},"expect":{"D2":"Reorder","D3":"OK","D4":"OK","D5":"Reorder"}},{"id":"reorder-point-changes","label":"flags update when reorder points change","overrides":{"C2":"40","C3":"5","C4":"29","C5":"100"},"expect":{"D2":"Reorder","D3":"OK","D4":"OK","D5":"Reorder"}}]'::jsonb, '2026-11-11T00:00:00Z'::timestamptz),
  ('4e2cde94-010e-5dec-a2c2-da00e668b7cb', '{"schemaVersion":1,"exerciseId":"sum-relative-refs","exerciseVersion":1,"expected":[{"id":"north-total","cell":"B5","value":358,"label":"North total"},{"id":"south-total","cell":"C5","value":287,"label":"South total"}],"requireFormula":["B5","C5"],"requireFunctions":{"B5":["SUM"],"C5":["SUM"]},"passThreshold":100}'::jsonb, '[{"id":"new-monthly-figures","label":"totals update when the monthly figures change","overrides":{"B2":"200","B3":"50","B4":"10","C2":"1","C3":"2","C4":"3"},"expect":{"B5":260,"C5":6}},{"id":"missing-month","label":"totals still work when a month is blank or zero","overrides":{"B4":"","C4":"0"},"expect":{"B5":215,"C5":190}}]'::jsonb, '2026-11-11T00:00:00Z'::timestamptz),
  ('79f8240c-dcab-5f51-8130-94b498e8a4de', '{"schemaVersion":1,"exerciseId":"xlookup-price-list","exerciseVersion":1,"expected":[{"id":"line-1","cell":"C2","value":2499,"label":"Line 1 unit price"},{"id":"line-2","cell":"C3","value":1999,"label":"Line 2 unit price"},{"id":"line-3","cell":"C4","value":899,"label":"Line 3 unit price (code typed in lower case)"},{"id":"line-4","cell":"C5","value":"Not listed","label":"Line 4 (code missing from the price list)"}],"requireFormula":["C2","C3","C4","C5"],"requireFunctions":{"C2":["XLOOKUP"],"C3":["XLOOKUP"],"C4":["XLOOKUP"],"C5":["XLOOKUP"]},"passThreshold":100}'::jsonb, '[{"id":"xlp-price-review","label":"prices come from the price list after a price review","overrides":{"G2":"2699","G3":"2149","G4":"949"},"expect":{"C2":2699,"C3":2149,"C4":949,"C5":"Not listed"}},{"id":"xlp-list-reordered","label":"prices are found by code, not by row position","overrides":{"E2":"SD-120","F2":"Ladies sandal","G2":"899","E3":"SL-075","F3":"Slipper","G3":"499","E4":"SS-210","F4":"School shoe","G4":"2499","E5":"SN-450","F5":"Canvas sneaker","G5":"1999","E6":"BT-330","F6":"Ankle boot","G6":"4599"},"expect":{"C2":2499,"C3":1999,"C4":899,"C5":"Not listed"}},{"id":"xlp-new-listing","label":"a newly listed product in the last row is found","overrides":{"E6":"GB-610","F6":"Gumboot","G6":"1299"},"expect":{"C2":2499,"C3":1999,"C4":899,"C5":1299}},{"id":"xlp-order-codes-change","label":"prices update when the order codes change","overrides":{"B2":"BT-330","B3":"XX-000","B4":"SL-075","B5":"sn-450"},"expect":{"C2":4599,"C3":"Not listed","C4":499,"C5":1999}}]'::jsonb, '2026-11-11T00:00:00Z'::timestamptz)
